package com.nexusduo.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;
public class NetworkActivity extends Activity{
 int BLUE=Color.rgb(0,61,165),CYAN=Color.rgb(0,184,255),INK=Color.rgb(18,38,72),MUTED=Color.rgb(92,112,145);int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));g.setStroke(dp(1),Color.rgb(214,228,250));return g;} TextView tv(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;} Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setAllCaps(false);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{BLUE,CYAN});g.setCornerRadius(dp(18));b.setBackground(g);b.setElevation(dp(8));b.setOnTouchListener((v,e)->{if(e.getAction()==0)v.animate().scaleX(.97f).scaleY(.97f).setDuration(80).start();else if(e.getAction()==1||e.getAction()==3)v.animate().scaleX(1).scaleY(1).setDuration(140).start();return false;});return b;}
 String caps(String n){switch(n){case"TikTok":return"✅ Site web intégré\n✅ Vidéos publiques / profils publics selon disponibilité\n↗ Certaines fonctions peuvent être limitées côté TikTok";case"Instagram":return"✅ Site web intégré\n✅ Publications publiques lorsque Meta les autorise\n↗ Certaines fonctions peuvent être limitées côté Meta";case"Facebook":return"✅ Site web intégré\n✅ Pages / publications publiques lorsque Facebook les autorise\n↗ Contenu privé selon les règles Facebook";case"Twitch":return"✅ Site web intégré\n✅ Streams, VOD et clips publics\n✅ Chat selon disponibilité";case"YouTube":return"✅ Site web intégré\n✅ Vidéos et playlists publiques\n✅ Lecture dans Nexus Duo";case"X":return"✅ Site web intégré\n✅ Publications / profils publics selon disponibilité";case"Pinterest":return"✅ Site web intégré\n✅ Pins / tableaux publics selon disponibilité";case"Reddit":return"✅ Site web intégré\n✅ Publications et communautés publiques";case"Threads":return"✅ Site web intégré\n✅ Liens publics selon disponibilité";case"LinkedIn":return"✅ Site web intégré\n↗ Plusieurs contenus exigent une session LinkedIn";case"Discord":return"✅ Discord Web intégré\n↗ Certaines fonctions avancées peuvent être limitées";case"Snapchat":return"✅ Snapchat Web lorsque disponible\n↗ Plusieurs fonctions restent limitées sur le Web";default:return"✅ Site web intégré\n↗ Ouverture externe disponible manuellement";}}
 boolean hostMatches(String n,String u){try{String h=Uri.parse(u).getHost();if(h==null)return false;h=h.toLowerCase();if(n.equals("TikTok"))return h.contains("tiktok.com");if(n.equals("Instagram"))return h.contains("instagram.com");if(n.equals("Facebook"))return h.contains("facebook.com")||h.contains("fb.watch");if(n.equals("X"))return h.equals("x.com")||h.endsWith("twitter.com");if(n.equals("Twitch"))return h.contains("twitch.tv");if(n.equals("YouTube"))return h.contains("youtube.com")||h.equals("youtu.be");if(n.equals("Snapchat"))return h.contains("snapchat.com");if(n.equals("Pinterest"))return h.contains("pinterest.")||h.equals("pin.it");if(n.equals("Reddit"))return h.contains("reddit.com")||h.equals("redd.it");if(n.equals("Threads"))return h.contains("threads.net");if(n.equals("LinkedIn"))return h.contains("linkedin.com");if(n.equals("Discord"))return h.contains("discord.com")||h.contains("discord.gg");}catch(Exception e){}return false;}
 void openInternal(String name,String url){Intent i=new Intent(this,BrowserActivity.class);i.putExtra("name",name);i.putExtra("url",url);startActivity(i);overridePendingTransition(android.R.anim.fade_in,android.R.anim.fade_out);} void openExternal(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"Impossible d’ouvrir ce lien",Toast.LENGTH_SHORT).show();}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);String name=getIntent().getStringExtra("name"),url=getIntent().getStringExtra("url");ScrollView sv=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(18),dp(24),dp(18),dp(30));r.setBackgroundColor(Color.rgb(247,251,255));TextView back=tv("‹  Retour",16,BLUE);back.setTypeface(null,1);back.setOnClickListener(v->finish());r.addView(back,new LinearLayout.LayoutParams(-1,dp(42)));TextView title=tv(name,31,INK);title.setTypeface(null,1);r.addView(title,new LinearLayout.LayoutParams(-1,dp(54)));TextView sub=tv("Mini-app Web • mode clair cyberpunk Québec",14,MUTED);r.addView(sub,new LinearLayout.LayoutParams(-1,dp(48)));Button inside=btn("🌐  Ouvrir dans Nexus Duo");inside.setOnClickListener(v->openInternal(name,url));r.addView(inside,new LinearLayout.LayoutParams(-1,dp(56)));Space s1=new Space(this);r.addView(s1,new LinearLayout.LayoutParams(1,dp(10)));Button outside=btn("↗  Ouvrir à l’extérieur volontairement");outside.setOnClickListener(v->openExternal(url));r.addView(outside,new LinearLayout.LayoutParams(-1,dp(56)));TextView allowed=tv("CE QUI PEUT ÊTRE INTÉGRÉ",12,BLUE);allowed.setTypeface(null,1);allowed.setPadding(0,dp(24),0,dp(10));r.addView(allowed);TextView info=tv(caps(name),14,INK);info.setPadding(dp(16),dp(16),dp(16),dp(16));info.setBackground(bg(Color.WHITE,18));info.setElevation(dp(8));r.addView(info,new LinearLayout.LayoutParams(-1,-2));TextView pasteTitle=tv("INTÉGRER UN LIEN PUBLIC",12,BLUE);pasteTitle.setTypeface(null,1);pasteTitle.setPadding(0,dp(24),0,dp(10));r.addView(pasteTitle);EditText e=new EditText(this);e.setHint("Collez ici un lien "+name);e.setHintTextColor(Color.rgb(135,151,177));e.setTextColor(INK);e.setSingleLine(true);e.setPadding(dp(14),0,dp(14),0);e.setBackground(bg(Color.WHITE,16));e.setElevation(dp(5));r.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));Space s2=new Space(this);r.addView(s2,new LinearLayout.LayoutParams(1,dp(10)));Button embed=btn("＋  Vérifier et intégrer dans Nexus Duo");embed.setOnClickListener(v->{String u=e.getText().toString().trim();if(u.length()==0){Toast.makeText(this,"Collez d’abord un lien",Toast.LENGTH_SHORT).show();return;}if(!u.startsWith("http://")&&!u.startsWith("https://"))u="https://"+u;if(!hostMatches(name,u)){Toast.makeText(this,"Ce lien ne semble pas appartenir à "+name,Toast.LENGTH_LONG).show();return;}openInternal(name+" • intégré",u);});r.addView(embed,new LinearLayout.LayoutParams(-1,dp(56)));TextView note=tv("⚡ Rester dans Nexus est actif. Les limites imposées par chaque réseau restent applicables.",12,MUTED);note.setPadding(0,dp(16),0,0);r.addView(note);sv.addView(r);setContentView(sv);}
}
